# MIG19g: shared, field-scoped presentation only. Never modify the RenderModel.
function ConvertTo-RuDisplayAttribute19g {
    param([AllowNull()][string]$Name,[AllowNull()][string]$Text)
    if ([string]::IsNullOrEmpty($Name) -or [string]::IsNullOrEmpty($Text)) { return $Text }
    $result = $Text
    # Generic words such as Enabled or Never can also be actual AD names.
    # Restrict generic status/unit translation to known presentation fields.
    if ($Name -in @('anonymousLDAPAccess','anonymousNSPIAccess','recycleBin','tombstoneLifetime',
        'maxTicketAgeTGT','maxRenewalAge','maxServiceTicketAge','maxClockSkew','krbtgtPasswordAge',
        'accountStatus','siteSubnets','minPwdLength','passwordComplexity','minPwdAge','maxPwdAge',
        'pwdHistoryLength','reversibleEncryption','lockoutThreshold','lockoutDuration','lockoutObservationWindow',
        'dSHeuristics','adminSDHolderExclusion','principalNameUniqueness','LDAPSigning','ChannelBinding',
        'anonymousSamEnumeration','anonymousSidNameTranslation','ServerSigning','ClientSigning',
        'EffectiveSetting','decidedBy','GPOStatus','activityStatus','PrivilegeCategory','accountexpires',
        'pwdLastSet','lastlogon','lastLogonTimestamp','lastlogoff','badpasswordtime','iscriticalsystemobject')) {
        $result = ConvertTo-RuReportAttributeValue -Text $result
    }
    $result = ConvertTo-RuReportAttributeContext7 -Name $Name -Text $result
    $result = ConvertTo-RuReportAttributeContext8 -Name $Name -Text $result
    switch ($Name) {
        'ownerKind' {
            if ($result -ceq 'User account') { return 'Учётная запись пользователя' }
        }
        'ownerIsCreator' {
            if ($result -ceq 'Unknown - the object records no creator') { return 'Неизвестно — создатель объекта не указан' }
            if ($result -ceq 'True') { return 'Да' }
            if ($result -ceq 'False') { return 'Нет' }
        }
        'lapsProtected' {
            if ($result -cmatch '^(\d+) of (\d+) computers \((\d+(?:[.,]\d+)?)%\) - the LAPS schema is not present in Active Directory$') {
                return [regex]::Replace($result,'^(\d+) of (\d+) computers \((\d+(?:[.,]\d+)?)%\) - the LAPS schema is not present in Active Directory$','$1 из $2 компьютеров ($3%) — схема LAPS отсутствует в Active Directory')
            }
            if ($result -cmatch '^(\d+) of (\d+) computers \((\d+(?:[.,]\d+)?)%\)$') {
                return [regex]::Replace($result,'^(\d+) of (\d+) computers \((\d+(?:[.,]\d+)?)%\)$','$1 из $2 компьютеров ($3%)')
            }
        }
        'lapsUnprotected' {
            if ($result -cmatch '^(\d+) of (\d+) computers \((\d+(?:[.,]\d+)?)%\)$') {
                return [regex]::Replace($result,'^(\d+) of (\d+) computers \((\d+(?:[.,]\d+)?)%\)$','$1 из $2 компьютеров ($3%)')
            }
        }
    }
    return $result
}
